//go:build audit

package arapuca

/*
#include <stdlib.h>
#include <stdint.h>
#include <arapuca.h>

// The trampoline is generated by //export in audit.go; declare it
// here so its address can be passed to arapuca_config_set_audit_callback.
extern void goAuditTrampoline(const char *event_json, uintptr_t event_json_len, void *user_data);
*/
import "C"

import (
	"errors"
	"fmt"
	"runtime"
	"unsafe"
)

// setAuditCallback registers the handler and wires the trampoline into
// the config. The registration key rides in C-allocated memory (C
// holds user_data until cleanup returns, so a Go pointer must not be
// used), and the slot is freed by releaseAuditRegistration.
func setAuditCallback(lcfg *C.struct_arapuca_ArapucaConfig, handler func(AuditEvent)) (auditRegistration, error) {
	key := registerAuditHandler(handler)
	slot := (*C.uint64_t)(C.malloc(C.sizeof_uint64_t))
	if slot == nil {
		unregisterAuditHandler(key)
		return auditRegistration{}, errors.New("arapuca: audit registration: out of memory")
	}
	*slot = C.uint64_t(key)

	runtime.LockOSThread()
	rc := C.arapuca_config_set_audit_callback(
		lcfg,
		(C.arapuca_ArapucaAuditCallback)(C.goAuditTrampoline),
		unsafe.Pointer(slot),
	)
	var err error
	if rc != 0 {
		err = fmt.Errorf("arapuca: set audit callback: %s", lastError())
	}
	runtime.UnlockOSThread()

	if err != nil {
		C.free(unsafe.Pointer(slot))
		unregisterAuditHandler(key)
		return auditRegistration{}, err
	}
	return auditRegistration{key: key, slot: unsafe.Pointer(slot)}, nil
}

// releaseAuditRegistration frees the C slot and drops the handler. It
// must run only after the C call that can still emit events
// (arapuca_launch on the error path, arapuca_process_cleanup
// otherwise) has returned.
func releaseAuditRegistration(r auditRegistration) {
	if r.slot == nil {
		return
	}
	key := uint64(*(*C.uint64_t)(r.slot))
	C.free(r.slot)
	unregisterAuditHandler(key)
}
